document.addEventListener('DOMContentLoaded', function() {
  const recordBtn = document.getElementById('record-btn');
  const stopBtn = document.getElementById('stop-btn');
  const micSelect = document.getElementById('mic-select');
  const recordingTime = document.getElementById('recording-time');
  const statusMessage = document.getElementById('status-message');
  const statusAlert = document.getElementById('status-alert');
  const playbackSection = document.getElementById('playback-section');
  const audioPlayback = document.getElementById('audio-playback');
  const downloadMp3Btn = document.getElementById('download-mp3-btn');
  const downloadWavBtn = document.getElementById('download-wav-btn');
  const newRecordingBtn = document.getElementById('new-recording-btn');
  const waveformCanvas = document.getElementById('waveform');
  const waveformCtx = waveformCanvas.getContext('2d');

  let mediaRecorder = null;
  let audioChunks = [];
  let audioBlob = null;
  let audioStream = null;
  let audioContext = null;
  let analyser = null;
  let animationId = null;
  let startTime = null;
  let timerInterval = null;

  // Resize canvas
  function resizeCanvas() {
    waveformCanvas.width = waveformCanvas.offsetWidth;
    waveformCanvas.height = waveformCanvas.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Get audio devices
  async function getAudioDevices() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());

      const devices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = devices.filter(d => d.kind === 'audioinput');

      micSelect.innerHTML = '';
      audioInputs.forEach((device, index) => {
        const option = document.createElement('option');
        option.value = device.deviceId;
        option.text = device.label || `Microphone ${index + 1}`;
        micSelect.appendChild(option);
      });
      micSelect.disabled = false;
    } catch (error) {
      updateStatus('danger', 'Microphone access denied. Please allow microphone permissions.');
    }
  }

  // Update status
  function updateStatus(type, message) {
    statusAlert.className = `alert alert-${type}`;
    statusMessage.innerHTML = message;
  }

  // Format time
  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
    const secs = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${mins}:${secs}`;
  }

  // Draw waveform
  function drawWaveform() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteTimeDomainData(dataArray);

    waveformCtx.fillStyle = '#f8f9fa';
    waveformCtx.fillRect(0, 0, waveformCanvas.width, waveformCanvas.height);

    waveformCtx.lineWidth = 2;
    waveformCtx.strokeStyle = '#0055FF';
    waveformCtx.beginPath();

    const sliceWidth = waveformCanvas.width / bufferLength;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const v = dataArray[i] / 128.0;
      const y = v * waveformCanvas.height / 2;

      if (i === 0) {
        waveformCtx.moveTo(x, y);
      } else {
        waveformCtx.lineTo(x, y);
      }
      x += sliceWidth;
    }

    waveformCtx.lineTo(waveformCanvas.width, waveformCanvas.height / 2);
    waveformCtx.stroke();

    animationId = requestAnimationFrame(drawWaveform);
  }

  // Start recording
  async function startRecording() {
    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);

      // Setup audio context and analyser
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
      analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(audioStream);
      source.connect(analyser);
      analyser.fftSize = 2048;

      // Start visualization
      drawWaveform();

      // Setup media recorder
      mediaRecorder = new MediaRecorder(audioStream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunks.push(event.data);
      };

      mediaRecorder.onstop = () => {
        audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
        const audioUrl = URL.createObjectURL(audioBlob);
        audioPlayback.src = audioUrl;
        playbackSection.classList.remove('d-none');
        updateStatus('success', 'Recording complete! Preview your recording below.');
      };

      mediaRecorder.start();
      startTime = Date.now();

      // Start timer
      timerInterval = setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        recordingTime.textContent = formatTime(elapsed);
      }, 100);

      recordBtn.disabled = true;
      stopBtn.disabled = false;
      micSelect.disabled = true;
      updateStatus('danger', '<span class="recording-indicator d-inline-block me-2"></span>Recording in progress...');
    } catch (error) {
      updateStatus('danger', 'Error starting recording: ' + error.message);
    }
  }

  // Stop recording
  function stopRecording() {
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      mediaRecorder.stop();
    }

    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
    }

    if (animationId) {
      cancelAnimationFrame(animationId);
    }

    if (timerInterval) {
      clearInterval(timerInterval);
    }

    recordBtn.disabled = false;
    stopBtn.disabled = true;
    micSelect.disabled = false;
  }

  // Download as WAV
  function downloadWav() {
    if (!audioBlob) return;
    const url = URL.createObjectURL(audioBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recording_${Date.now()}.wav`;
    a.click();
    URL.revokeObjectURL(url);
  }

  // Download as MP3 (using WAV for now - MP3 encoding requires additional library)
  function downloadMp3() {
    // For simplicity, downloading as WAV (MP3 encoding would require lamejs or similar)
    if (!audioBlob) return;
    const url = URL.createObjectURL(audioBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recording_${Date.now()}.wav`;
    a.click();
    URL.revokeObjectURL(url);
    updateStatus('info', 'Downloaded as WAV format. MP3 conversion requires additional processing.');
  }

  // New recording
  function newRecording() {
    playbackSection.classList.add('d-none');
    recordingTime.textContent = '00:00';
    audioPlayback.src = '';
    audioBlob = null;
    audioChunks = [];
    updateStatus('info', 'Click the record button to start a new recording.');

    // Clear canvas
    waveformCtx.fillStyle = '#f8f9fa';
    waveformCtx.fillRect(0, 0, waveformCanvas.width, waveformCanvas.height);
  }

  // Event listeners
  recordBtn.addEventListener('click', startRecording);
  stopBtn.addEventListener('click', stopRecording);
  downloadWavBtn.addEventListener('click', downloadWav);
  downloadMp3Btn.addEventListener('click', downloadMp3);
  newRecordingBtn.addEventListener('click', newRecording);

  // Initialize
  getAudioDevices();
});

