/* mic-recorder.json — restyled from old .recorder-btn/.recording-indicator/.waveform-container/.recording-time block */
.recorder-btn{width:80px;height:80px;border-radius:50%;font-size:2rem;padding:0;}
.recording-time{font-size:2.5rem;font-weight:700;color:var(--ink);}
.waveform-container{height:150px;background:var(--panel-2);border:1px solid var(--border);border-radius:8px;overflow:hidden;}
#waveform{width:100%;height:100%;display:block;}
.recording-indicator{width:12px;height:12px;background-color:var(--red);border-radius:50%;animation:pulse-opacity 1s infinite;}
@keyframes pulse-opacity{0%,100%{opacity:1}50%{opacity:.5}}
.d-inline-block{display:inline-block;}
/* #status-alert: the tool script overwrites this element's className to a bare "alert alert-<type>"
   string on every status update, so the structural box styling normally supplied by .status-message
   must live on the id selector to survive those updates. */
#status-alert{padding:.6rem .85rem;margin-bottom:.85rem;border-radius:4px;font-size:13px;border:1px solid var(--border);}
